int leastOpsExpressTarget(int x, int target) {
    if (x == target) return 0;
    if (target == 1) return 1;
    if (x > target) return min(2 * target - 1, 2 * (x - target));

    int k = 0;
    long long p = x;
    while (p < target) {
        k++;
        p *= x;
    }

    int ans = INT_MAX;
    long long d = 1;

    for (int i = k - 1; i >= 0; i--) {
        while (p >= target + d * (1 - x)) {
            p -= d;
            ans = min(ans, i + (int) (log2(target / d) + 1) + (int) (d == 1 ? -1 : 0));
        }
        d = d * x + 1;
    }

    return ans;
}
```

