from typing import List

def permuteUnique(nums: List[int]) -> List[List[int]]:
    def backtrack(start):
        if start == len(nums):
            result.append(nums[:])
        for i in range(start, len(nums)):
            if i > start and nums[i] == nums[start]:
                continue
            nums[start], nums[i] = nums[i], nums[start]
            backtrack(start + 1)
            nums[start], nums[i] = nums[i], nums[start]

    nums.sort()
    result = []
    backtrack(0)
    return result

def count_unique_permutations(nums: List[int]) -> int:
    nums.sort()
    result = 1
    for i in range(1, len(nums)):
        if nums[i] != nums[i - 1]:
            result *= i + 1
    return result
